// Source of the "API" ModuleScript the bridge puts in CoreGui.AILabs. Plain Luau so any context can require it.
export const API_SOURCE = `--!strict
-- AI Labs agent API (generated by the AI Labs plugin, a UI Labs fork; see AGENTS.md)
--   local ui = require(game:GetService("CoreGui").AILabs.API)
--   ui.open("ui/crops/sell-page", { controls = { tab = "gear" }, capture = "phone" })
local invoke = script.Parent:WaitForChild("Invoke") :: BindableFunction

local function call(command: string, args: any?): any
	if args ~= nil and typeof(args) ~= "table" then
		error("[AI Labs] " .. command .. ": arguments must be a table", 2)
	end
	local response = invoke:Invoke(command, args or {})
	if not response.ok then
		error("[AI Labs] " .. tostring(response.error), 2)
	end
	return response.result
end

local ui = {}

-- Raw access: ui.call("open", { story = ... })
ui.call = call

function ui.status() return call("status") end
function ui.list(filter: string?) return call("list", { filter = filter }) end
-- open the AI Labs window (true) or close it (false); nil just reports
function ui.window(open: boolean?) return call("window", { open = open }) end
-- Works in the user's AI Labs window (opens it; show = false keeps it closed). Reuses the open tab when it's the
-- same story (fresh = true remounts), otherwise switches it. opts: widget (own window, avoid), controls, capture (preset/Vector2/{width,height}),
--       background (Color3), backgroundTransparency, timeout
-- also accepts ui.open({ story = ..., controls = ... })
function ui.open(story: any, opts: { [string]: any }?)
	local args
	if typeof(story) == "table" then
		args = table.clone(story)
	else
		args = table.clone(opts or {})
		args.story = story
	end
	return call("open", args)
end
function ui.close(key: string?) return call("close", { key = key }) end
function ui.closeAll() return call("close", { key = "all" }) end
function ui.controls(key: string?) return call("controls", { key = key }) end
function ui.set(controls: { [string]: any }, key: string?) return call("set", { controls = controls, key = key }) end
function ui.reload(key: string?) return call("reload", { key = key }) end
-- capture: preset name ("fill", "phone", "phonePortrait", "tablet", "laptop", "desktop"), Vector2, {width, height},
-- or false to put the story back in the AI Labs window
function ui.capture(capture: any?, opts: { [string]: any }?)
	if typeof(capture) == "table" and opts == nil and capture.width == nil and capture[1] == nil then
		opts = capture
		capture = opts.capture
	end
	local args = table.clone(opts or {})
	args.capture = if capture == nil then "fill" else capture
	return call("capture", args)
end
-- turn on a tool: "select" (Select Elements), "comment" (Comment For AI), "tweak" (Tweak Properties) or "none"
function ui.tool(name: string?) return call("tool", { name = name }) end
-- GUI inset overlay: Roblox top bar band + phone safe areas over the story (true/false). ui.capture(size, { inset = true })
-- and ui.open(story, { inset = true }) turn it on too. Stories read it via Environment.GetEnvGlobalInjection().GetGuiInset()
function ui.inset(on: boolean?, key: string?) return call("inset", { on = if on == nil then true else on, key = key }) end
function ui.zoom(zoom: number?, key: string?) return call("zoom", { zoom = zoom, key = key, reset = true }) end
-- GUI tree of the story (names, classes, rects relative to the story root, texts, images)
function ui.tree(opts: { [string]: any }?) return call("tree", opts or {}) end
function ui.logs(since: number?) return call("logs", { since = since }) end
-- comments people left with the Comment tool (unresolved; opts.all includes resolved, opts.story filters)
function ui.comments(opts: { [string]: any }?) return call("comments", opts or {}) end
-- claim an item before working on it (shows "In progress" in the user's Comments panel), then resolve it with a note
-- of what changed: ui.resolveComment(id, "Made the title icon 70px").  ui.resolveComment(id, false) reopens it.
-- mark an item read (shows "Seen" in the user's panel); by = your session name. ui.comments({ markSeen = true, by = ... })
-- marks everything it returns.
-- leave a comment about the whole open story (scope = "story", no element)
function ui.addComment(text: string, key: string?) return call("addComment", { text = text, key = key }) end
function ui.seenComment(id: string, by: string?) return call("seenComment", { id = id, by = by }) end
function ui.seenTweak(id: string, by: string?) return call("seenTweak", { id = id, by = by }) end
function ui.claimComment(id: string, note: string?) return call("claimComment", { id = id, note = note }) end
function ui.resolveComment(id: string, noteOrResolved: any?, note: string?)
	if typeof(noteOrResolved) == "string" then return call("resolveComment", { id = id, note = noteOrResolved }) end
	return call("resolveComment", { id = id, resolved = noteOrResolved, note = note })
end
-- property tweaks people made with the Tweak tool (unresolved; opts.all includes resolved, opts.story filters).
-- Each: element, target ("" or a child class like "UICorner"), property, old/new (text) + oldValue/newValue (typed),
-- controls and viewport size at the time
function ui.tweaks(opts: { [string]: any }?) return call("tweaks", opts or {}) end
-- apply + record a tweak from a script: ui.tweak({ element = path, property = "TextSize", value = 24, target = "" })
function ui.tweak(opts: { [string]: any }) return call("tweak", opts) end
-- click an element in the story: { element = path } or { x = , y = } (relative to the story root).
-- TextBoxes: pass text = "..." to type it (submit = false to not fire FocusLost as Enter). Buttons can't be pressed
-- from Edit mode, so they get an "AI: please click here" highlight for the user and { clicked = false, reason }.
function ui.click(target: any, opts: { [string]: any }?)
	local args = table.clone(opts or {})
	if typeof(target) == "string" then args.element = target
	elseif typeof(target) == "table" then for k, v in target do args[k] = v end end
	return call("click", args)
end
function ui.claimTweak(id: string, note: string?) return call("claimTweak", { id = id, note = note }) end
function ui.resolveTweak(id: string, noteOrResolved: any?, note: string?)
	if typeof(noteOrResolved) == "string" then return call("resolveTweak", { id = id, note = noteOrResolved }) end
	return call("resolveTweak", { id = id, resolved = noteOrResolved, note = note })
end
-- opts: { id = ... } | { story = ... } | { resolved = true } | { all = true }; restore = false keeps the tweaked values
function ui.clearTweaks(opts: { [string]: any }) return call("clearTweaks", opts) end
-- show the original values (true) or the tweaked ones (false)
function ui.showOriginal(original: boolean?) return call("showOriginal", { original = if original == nil then true else original }) end
function ui.deleteComments(opts: { [string]: any }) return call("deleteComments", opts) end

return ui
`;
